<section class="card"><h2>Crear anuncio para la plataforma</h2><form method="post" class="profile-grid"><input type="hidden" name="crear_anuncio_superadmin" value="1"><label>Título<input name="titulo" required></label><label>Enlace opcional<input name="enlace"></label><label class="wide">Mensaje<textarea name="contenido" rows="3" required></textarea></label><label>Alcance<select name="audiencia" id="audienciaAnuncio"><option value="global">Todas las barberías</option><option value="barberia">Una barbería</option></select></label><label id="barberiaDestino">Barbería<select name="barberia_id"><?php foreach ($barberias as $barberia): ?><option value="<?php echo $barberia['id']; ?>"><?php echo htmlspecialchars($barberia['nombre']); ?></option><?php endforeach; ?></select></label><fieldset class="wide" style="border:1px solid #293548;border-radius:8px;padding:10px"><legend class="muted">Mostrar a</legend><label style="display:inline-flex;margin-right:16px"><input type="checkbox" name="roles_destino[]" value="admin" checked> Administradores</label><label style="display:inline-flex;margin-right:16px"><input type="checkbox" name="roles_destino[]" value="barbero" checked> Barberos</label><label style="display:inline-flex"><input type="checkbox" name="roles_destino[]" value="cliente" checked> Clientes</label></fieldset><button class="wide">Publicar anuncio</button></form></section>
<section class="card table"><h2>Anuncios publicados</h2><table><tr><th>Título</th><th>Alcance</th><th>Destinatarios</th><th>Estado</th><th>Acción</th></tr><?php foreach ($anuncios_superadmin as $anuncio): ?><tr><td><?php echo htmlspecialchars($anuncio['titulo']); ?></td><td><?php echo $anuncio['audiencia'] === 'global' ? 'Todas las barberías' : htmlspecialchars($anuncio['barberia_nombre'] ?? 'Barbería'); ?></td><td><?php echo htmlspecialchars($anuncio['roles_destino']); ?></td><td><?php echo $anuncio['estado'] ? 'Activo' : 'Inactivo'; ?></td><td><div class="actions"><a class="btn small" href="superadmin.php?toggle_anuncio_superadmin=<?php echo $anuncio['id']; ?>">Activar/desactivar</a><a class="btn small danger" href="superadmin.php?delete_anuncio_superadmin=<?php echo $anuncio['id']; ?>" onclick="return confirm('¿Eliminar este anuncio?');">Eliminar</a></div></td></tr><?php endforeach; ?></table></section>
<section class="card table"><h2>Estadísticas de uso</h2><table><tr><th>Barbería</th><th>Clientes</th><th>Citas</th><th>Clientes consolidados</th><th>No regresaron</th><th>Inicios de sesión</th><th>Último acceso</th><th>Ingresos estimados</th></tr><?php foreach ($barberias as $barberia): $stat = $estadisticas[$barberia['id']]; ?><tr><td><?php echo htmlspecialchars($barberia['nombre']); ?></td><td><?php echo $stat['clientes']; ?></td><td><?php echo $stat['citas']; ?></td><td><?php echo $stat['consolidados']; ?></td><td><?php echo $stat['no_regresaron']; ?></td><td><?php echo $stat['accesos']; ?></td><td><?php echo htmlspecialchars($stat['ultimo_acceso']); ?></td><td>$<?php echo number_format($stat['ingresos'], 2, ',', '.'); ?></td></tr><?php endforeach; ?></table><p class="muted">Los ingresos son estimados a partir del precio configurado y las citas registradas.</p></section>
<script>document.getElementById('audienciaAnuncio')?.addEventListener('change',function(){var destino=document.getElementById('barberiaDestino');destino.style.display=this.value==='barberia'?'grid':'none';});document.getElementById('audienciaAnuncio')?.dispatchEvent(new Event('change'));</script>
